INSERT INTO "revisions" VALUES('c3f1aa036fa6d061c74f4e2439926d8776461ca1b193c52b64c9556ee4164582','legacy_result_boundaries','{"entry":"main.nex","files":{"main.nex":"module legacy_result_boundaries;\npub struct Box<T> { value:T; }\nfn identity<T>(value:T)->T { return value; }\nfn read(value:result<i64>)->result<str> {\n  match value { ok(n)=>{return ok(\"value=\"+str(n));} err(code,message)=>{return err(code,message);} }\n}\nfn main()->unit!{io} {\n  let propagate:Box<str> = Box(identity(\"Я\\u0000🦊\"));\n  print(propagate.value);\n  print(read(ok(42)));\n  print(read(err<i64>(\"OLD\", \"same error\")));\n}\ntest fn values()->unit {\n  assert(read(ok(42))==ok(\"value=42\"));\n  assert(read(err<i64>(\"OLD\", \"same error\"))==err<str>(\"OLD\", \"same error\"));\n}\n"},"schema":"nex.sources/1"}','/private/var/folders/hg/b7ggtzxs1pd_5jwc99gprqwh0000gq/T/nex-genuine016-7kaq4096/main.nex','2026-10-21T20:52:04.617Z','0.16');
